package com.multiaceites.controller; import com.multiaceites.dto.SaleRequest; import com.multiaceites.service.SaleService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/ventas") @RequiredArgsConstructor public class SaleController{private final SaleService s;@GetMapping public Object all(){return s.all();}@GetMapping("/{id}") public Object one(@PathVariable Long id){return s.one(id);}@PostMapping public Object create(@Valid @RequestBody SaleRequest r,Authentication a){return s.create(r,a.getName());}}
